59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
70	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
71	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
72	     */
73	    private static final Pattern EMAIL_PATTERN =
74	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    public OwnerRestControllerV1(ClinicService clinicService,
85	                                 OwnerMapper ownerMapper,
86	                                 PetMapper petMapper,
87	                                 VisitMapper visitMapper) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
97	        Collection<Owner> owners;
98	        if (lastName != null) {
99	            owners = this.clinicService.findOwnerByLastName(lastName);
100	        } else {
101	            owners = this.clinicService.findAllOwners();
102	        }
103	        if (owners.isEmpty()) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
112	        Owner owner = this.clinicService.findOwnerById(ownerId);
113	        if (owner == null) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
122	        List<String> missingFields = new ArrayList<>();
123	        if (isBlank(ownerFieldsDto.getFirstName())) {
124	            missingFields.add("firstName");
125	        }
126	        if (isBlank(ownerFieldsDto.getLastName())) {
127	            missingFields.add("lastName");
128	        }
129	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
130	        if (isBlank(normalizedAddress)) {
131	            missingFields.add("address");
132	        }
133	        if (isBlank(ownerFieldsDto.getCity())) {
134	            missingFields.add("city");
135	        }
136	        if (isBlank(ownerFieldsDto.getTelephone())) {
137	            missingFields.add("telephone");
138	        }
139	        if (!missingFields.isEmpty()) {
140	            throw new MissingOwnerFieldsException(missingFields);
141	        }
142	        ownerFieldsDto.setAddress(normalizedAddress);
143	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
144	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
145	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
146	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
147	            .toList();
148	        String householdId = null;
149	        if (!householdMembers.isEmpty()) {
150	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
151	                throw new DuplicateHouseholdException(
152	                    "an owner with the same last name and address already exists");
153	            }
154	            // Joining an existing household: share a stable identifier with every member,
155	            // backfilling any members created before the household was formed.
156	            householdId = householdId(lastName, normalizedAddress);
157	            for (Owner member : householdMembers) {
158	                if (!householdId.equals(member.getHouseholdId())) {
159	                    member.setHouseholdId(householdId);
160	                    this.clinicService.saveOwner(member);
161	                }
162	            }
163	        }
164	        String telephone = toE164(ownerFieldsDto.getTelephone());
165	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
166	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
167	        if (telephoneInUse) {
168	            throw new DuplicateTelephoneException(
169	                "an owner with the same E.164 telephone already exists");
170	        }
171	        ownerFieldsDto.setTelephone(telephone);
172	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
173	        HttpHeaders headers = new HttpHeaders();
174	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
175	        if (owner.getRegistrationDate() == null) {
176	            owner.setRegistrationDate(LocalDate.now());
177	        }
178	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
179	        owner.setHouseholdId(householdId);
180	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
181	        this.clinicService.saveOwner(owner);
182	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
183	        headers.setLocation(UriComponentsBuilder.newInstance()
184	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
185	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
191	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
192	        if (currentOwner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        currentOwner.setAddress(ownerFieldsDto.getAddress());
196	        currentOwner.setCity(ownerFieldsDto.getCity());
197	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
198	        currentOwner.setLastName(ownerFieldsDto.getLastName());
199	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
200	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
201	        this.clinicService.saveOwner(currentOwner);
202	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
203	    }
204	
205	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
206	    @Transactional
207	    @Override
208	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner == null) {
211	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	        }
213	        this.clinicService.deleteOwner(owner);
214	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
215	    }
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
220	        Owner owner = this.clinicService.findOwnerById(ownerId);
221	        if (owner == null) {
222	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	        }
224	        HttpHeaders headers = new HttpHeaders();
225	        Pet pet = petMapper.toPet(petFieldsDto);
226	        owner.setId(ownerId);
227	        pet.setOwner(owner);
228	        pet.getType().setName(null);
229	        this.clinicService.savePet(pet);
230	        PetDto petDto = petMapper.toPetDto(pet);
231	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
232	            .buildAndExpand(pet.getId()).toUri());
233	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
234	    }
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
239	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
240	        if (currentOwner != null) {
241	            Pet currentPet = this.clinicService.findPetById(petId);
242	            if (currentPet != null) {
243	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
244	                currentPet.setName(petFieldsDto.getName());
245	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
246	                this.clinicService.savePet(currentPet);
247	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
248	            }
249	        }
250	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
256	        HttpHeaders headers = new HttpHeaders();
257	        Visit visit = visitMapper.toVisit(visitFieldsDto);
258	        Pet pet = new Pet();
259	        pet.setId(petId);
260	        visit.setPet(pet);
261	        this.clinicService.saveVisit(visit);
262	        VisitDto visitDto = visitMapper.toVisitDto(visit);
263	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
264	            .buildAndExpand(visit.getId()).toUri());
265	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
266	    }
267	
268	
269	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
270	    @Override
271	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
272	        Owner owner = this.clinicService.findOwnerById(ownerId);
273	        if (owner != null) {
274	            Pet pet = owner.getPet(petId);
275	            if (pet != null) {
276	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
277	            }
278	        }
279	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
280	    }
281	
282	    private static boolean isBlank(String value) {
283	        return value == null || value.isBlank();
284	    }
285	
286	    /**
287	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
288	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
289	     * lower-cased so that last names are compared case-insensitively.
290	     */
291	    private static String normalizeHousehold(String value) {
292	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
293	    }
294	
295	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
296	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
297	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
298	
299	    /**
300	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
301	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
302	     * upper-cased, and common street-type abbreviations are expanded token-by-token
303	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
304	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
305	     * used for every address comparison (household-duplicate detection and the shared household id).
306	     */
307	    private static String normalizeAddress(String value) {
308	        if (value == null) {
309	            return "";
310	        }
311	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
312	        if (collapsed.isEmpty()) {
313	            return "";
314	        }
315	        String[] tokens = collapsed.split(" ");
316	        StringBuilder sb = new StringBuilder();
317	        for (int i = 0; i < tokens.length; i++) {
318	            if (i > 0) {
319	                sb.append(' ');
320	            }
321	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
322	        }
323	        return sb.toString();
324	    }
325	
326	    /**
327	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
328	     * deterministic function of the normalized last name and address, so every owner that
329	     * shares those values maps to the same identifier regardless of creation order.
330	     */
331	    private static String householdId(String normalizedLastName, String normalizedAddress) {
332	        String key = normalizedLastName + "\n" + normalizedAddress;
333	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
334	    }
335	
336	    /**
337	     * Builds the {@code customerCode} assigned to a new owner, formatted
338	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
339	     * owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last name,
340	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the number
341	     * of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
342	     */
343	    private String nextCustomerCode(String city, String lastName) {
344	        String city3 = prefix3(city);
345	        String last3 = prefix3(lastName);
346	        long sequence = this.clinicService.findAllOwners().stream()
347	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
348	            .count() + 1L;
349	        return String.format("%s-%s-%04d", city3, last3, sequence);
350	    }
351	
352	    /** Upper-cased first three letters (any non-letter removed) of the given value. */
353	    private static String prefix3(String value) {
354	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
355	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
356	    }
357	
358	    /**
359	     * Counts the existing owners that share the given first name and last name, compared
360	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
361	     * owner currently being created is saved), so it reflects how many namesakes preceded the
362	     * new owner.
363	     */
364	    private int countNamesakes(String firstName, String lastName) {
365	        return (int) this.clinicService.findAllOwners().stream()
366	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
367	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
368	            .count();
369	    }
370	
371	    /**
372	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
373	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
374	     * national one, a single leading {@code '0'} is dropped, and the default country code
375	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'},
376	     * otherwise an {@link InvalidTelephoneException} is raised (reported to the client as 400).
377	     */
378	    private static String toE164(String telephone) {
379	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
380	        String digits;
381	        if (cleaned.startsWith("+")) {
382	            digits = cleaned.substring(1);
383	        } else {
384	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
385	            digits = "61" + national;
386	        }
387	        if (!digits.matches("[0-9]{8,15}")) {
388	            throw new InvalidTelephoneException(
389	                "telephone must form a valid E.164 number with 8 to 15 digits");
390	        }
391	        return "+" + digits;
392	    }
393	
394	    /**
395	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
396	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
397	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
398	     * stored and returned in canonical form.
399	     */
400	    private static String normalizeEmail(String email) {
401	        if (isBlank(email)) {
402	            return null;
403	        }
404	        String trimmed = email.trim();
405	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
406	            throw new InvalidEmailException("email must be a syntactically valid address");
407	        }
408	        return trimmed.toLowerCase(Locale.ROOT);
409	    }
410	}
